MAKE CODE: Button LED Toggle
arduino
// Button LED Toggle
// Connects a push button between pin 2 and GND.
// Uses internal pull-up resistor on pin 2.
// LED is on pin 13.
// When button is pressed (reading LOW), LED turns ON.
// When button is released (reading HIGH), LED turns OFF.

const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Enable internal pull-up resistor
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, LOW); // Start with LED off
}

void loop() {
  int buttonState = digitalRead(buttonPin);

  if (buttonState == LOW) {
    // Button is pressed (connected to ground)
    digitalWrite(ledPin, HIGH);
  } else {
    // Button is released (pull-up makes it HIGH)
    digitalWrite(ledPin, LOW);
  }
}
END

